queries.exposure:
# Exposure of ${fund} to ${issuer}: positions held by the fund (and, when
# enabled, every fund in the same corporate family) on instruments issued by
# the issuer (and, when enabled, by its subsidiaries up to ${depth} levels).
SELECT ?holder ?holderName ?issuerEntity ?issuerEntityName ?instrument ?cusip ?class ?ticker
       (SUM(?v) AS ?value) (SUM(?q) AS ?quantity) (COUNT(?pos) AS ?positions) (MAX(?d) AS ?asOf)
WHERE {
  ${holderClause}
  ${issuerClause}
  ?holder tg:holds ?pos .
  ?pos tg:issuer ?issuerEntity ; tg:instrument ?instrument ;
       tg:value ?v ; tg:quantity ?q ; tg:asOf ?d .
  ?holder tg:name ?holderName .
  ?issuerEntity tg:name ?issuerEntityName .
  ?instrument tg:cusip ?cusip ; tg:instrumentClass ?class .
  OPTIONAL { ?instrument tg:ticker ?ticker }
}
GROUP BY ?holder ?holderName ?issuerEntity ?issuerEntityName ?instrument ?cusip ?class ?ticker
ORDER BY DESC(?value)

queries.lineage_up:
# Edges on the ancestor chain of ${iri}, at most ${depth} levels up.
SELECT ?child ?parent ?parentName (GROUP_CONCAT(DISTINCT ?t; separator=",") AS ?parentTypes)
WHERE {
  { BIND(${iri} AS ?child) } ${moreChildren}
  ?child tg:subsidiaryOf ?parent .
  ?parent tg:name ?parentName ; a ?t .
  FILTER(?t != tg:LegalEntity && ?t != tg:Counterparty)
}
GROUP BY ?child ?parent ?parentName

queries.lineage_down:
# Edges of the subsidiary tree under ${iri}, at most ${depth} levels down.
SELECT ?parent ?child ?childName ?jurisdiction (GROUP_CONCAT(DISTINCT ?t; separator=",") AS ?childTypes)
WHERE {
  { BIND(${iri} AS ?parent) } ${moreParents}
  ?child tg:subsidiaryOf ?parent ; tg:name ?childName ; a ?t .
  OPTIONAL { ?child tg:jurisdiction ?jurisdiction }
  FILTER(?t != tg:LegalEntity && ?t != tg:Counterparty)
}
GROUP BY ?parent ?child ?childName ?jurisdiction
ORDER BY ?childName

queries.neighbors:
# Adjacent entities of ${iri} for the explorer: parent, subsidiaries, and the
# strongest holding relationships in either direction.
SELECT ?other ?otherName ?rel ?weight (GROUP_CONCAT(DISTINCT ?t; separator=",") AS ?otherTypes)
WHERE {
  {
    { SELECT ?other ("PARENT" AS ?rel) (0 AS ?weight) WHERE { ${iri} tg:subsidiaryOf ?other } }
    UNION
    { SELECT ?other ("SUBSIDIARY" AS ?rel) (0 AS ?weight) WHERE { ?other tg:subsidiaryOf ${iri} } }
    UNION
    { SELECT ?other ("HOLDS" AS ?rel) (SUM(?v) AS ?weight)
      WHERE { ${iri} tg:holds ?p . ?p tg:issuer ?other ; tg:value ?v } GROUP BY ?other }
    UNION
    { SELECT ?other ("HELD_BY" AS ?rel) (SUM(?v) AS ?weight)
      WHERE { ?other tg:holds ?p . ?p tg:issuer ${iri} ; tg:value ?v } GROUP BY ?other }
  }
  ?other tg:name ?otherName ; a ?t .
  FILTER(?t != tg:LegalEntity && ?t != tg:Counterparty)
}
GROUP BY ?other ?otherName ?rel ?weight
ORDER BY ?rel DESC(?weight) ?otherName
LIMIT ${limit}

queries.search:
SELECT ?e ?name ?ticker ?cik (GROUP_CONCAT(DISTINCT ?t; separator=",") AS ?types)
WHERE {
  ?e a tg:LegalEntity ; tg:name ?name ; a ?t .
  OPTIONAL { ?e tg:ticker ?ticker }
  OPTIONAL { ?e tg:cik ?cik }
  FILTER(?t != tg:LegalEntity && ?t != tg:Counterparty)
  FILTER(CONTAINS(LCASE(?name), ${qLower}) || LCASE(?ticker) = ${qLower} || ?cik = ${q})
}
GROUP BY ?e ?name ?ticker ?cik
ORDER BY DESC(COALESCE(LCASE(?ticker) = ${qLower}, false)) STRLEN(?name) ?name
LIMIT ${limit}

queries.stats:
SELECT ?entities ?issuers ?funds ?subsidiaries ?positions ?filings ?lineageEdges ?triples
WHERE {
  { SELECT (COUNT(DISTINCT ?e) AS ?entities) WHERE { ?e a tg:LegalEntity } }
  { SELECT (COUNT(DISTINCT ?i) AS ?issuers) WHERE { ?i a tg:Issuer } }
  { SELECT (COUNT(DISTINCT ?f) AS ?funds) WHERE { ?f a tg:Fund } }
  { SELECT (COUNT(DISTINCT ?s) AS ?subsidiaries) WHERE { ?s a tg:Subsidiary } }
  { SELECT (COUNT(DISTINCT ?p) AS ?positions) WHERE { ?p a tg:Position } }
  { SELECT (COUNT(DISTINCT ?g) AS ?filings) WHERE { ?g a tg:Filing } }
  { SELECT (COUNT(*) AS ?lineageEdges) WHERE { ?a tg:subsidiaryOf ?b } }
  { SELECT (COUNT(*) AS ?triples) WHERE { ?x ?y ?z } }
}
